python3 - <<'PY'
from collections import deque
pieces=[('virus','h',[(0,0),(1,0)],0,2,1),('cyan','v',[(0,0),(0,1)],2,1,0),('yellow','v',[(0,0),(0,1),(0,2)],4,0,0),('lime','h',[(0,0),(1,0),(2,0)],2,3,0),('blue','v',[(0,0),(0,1),(1,1)],0,3,0),('purple','h',[(0,0),(1,0)],1,5,0),('orange','v',[(0,0),(0,1)],0,0,0),('pink','h',[(0,0),(1,0)],2,0,0)]
start=tuple((p[3],p[4]) for p in pieces)
def solve(s):
 q=deque([s]); prev={s:None}
 while q:
  st=q.popleft()
  if st[0][0]>=5:
   path=[]
   while prev[st]: path.append(prev[st][1]);st=prev[st][0]
   return path[::-1]
  occ={}
  for i,p in enumerate(pieces):
   x,y=st[i]
   for dx,dy in p[2]:occ[x+dx,y+dy]=i
  for i,(name,axis,coords,_,__,target) in enumerate(pieces):
   x,y=st[i]
   for step in [-1,1]:
    xx,yy=x,y
    while 1:
     xx+=step if axis=='h' else 0; yy+=step if axis=='v' else 0
     if yy<0 or yy>=6 or xx<0 or (xx>=6 and not target):break
     if any(yy+dy!=2 for dx,dy in coords if xx+dx>=6):break
     if any((xx+dx,yy+dy) in occ and occ[(xx+dx,yy+dy)]!=i for dx,dy in coords if xx+dx<6):break
     ns=list(st);ns[i]=(xx,yy);ns=tuple(ns)
     if ns not in prev:prev[ns]=(st,(name,xx-x,yy-y));q.append(ns)
path=solve(start)
print('solvable',bool(path),'moves',len(path) if path else None)
print(path)
